// Replays flutter/test/goldens/quickadd_goldens.json, generated by executing
// the real addQuickAdd and removeQuickAdd out of mobile/app/preferences.js.
//
// What is locked is which additions are ACCEPTED and what the list looks like
// afterwards. A preset that exists in one app and not the other is a button
// somebody taps out of habit while nothing happens, and they have no way to
// tell whether the app is broken or they typed the amount wrong.
//
// The refusal SENTENCES are deliberately not locked to RN, because RN has
// none: it returns silently on every invalid input. Those are asserted
// separately below as this app's own addition.

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:salapify/money/quick_adds.dart';

List<QuickAdd> _list(dynamic raw) => [
  for (final q in raw as List)
    QuickAdd(
      (q as Map)['label'] as String,
      // The generator writes a non finite amount as a sentinel, because JSON
      // cannot carry one. None of the accepted cases produce it; the marker
      // exists so a regression that started accepting Infinity would show up
      // as a crash here rather than as a silent null.
      q['amount'] == '__nonfinite__'
          ? double.infinity
          : (q['amount'] as num).toDouble(),
    ),
];

void main() {
  final g =
      jsonDecode(File('test/goldens/quickadd_goldens.json').readAsStringSync())
          as Map<String, dynamic>;
  final start = _list(g['start']);

  test('every add and remove lands exactly where RN lands', () {
    final cases = (g['cases'] as List).cast<Map<String, dynamic>>();
    expect(cases, isNotEmpty);
    for (final c in cases) {
      // Two fixtures record inputs RN accepts and this app refuses on
      // purpose, asserted by name below. Skipped here so the replay stays a
      // statement about RN rather than a place a divergence hides.
      if ((c['name'] as String).startsWith('RN accepts')) continue;
      final want = _list(c['list']);
      final List<QuickAdd> got;
      if (c['kind'] == 'add') {
        final r = addQuickAdd(
          start,
          c['label'] as String,
          c['amount'] as String,
        );
        // RN leaves the list untouched when it refuses, so a refusal and an
        // unchanged list are the same observation there.
        got = r.list ?? start;
        expect(
          r.list != null,
          c['accepted'],
          reason: 'acceptance for ${c['name']}',
        );
      } else {
        got = removeQuickAdd(start, c['index'] as int);
      }
      expect(got.length, want.length, reason: '${c['name']} length');
      for (var i = 0; i < want.length; i++) {
        expect(
          got[i].label,
          want[i].label,
          reason: '${c['name']} row $i label',
        );
        expect(
          got[i].amount,
          want[i].amount,
          reason: '${c['name']} row $i amount',
        );
      }
    }
  });

  test('adding to a list that was never set works', () {
    final r = addQuickAdd(const [], 'First', '75');
    expect(r.list, isNotNull);
    expect(
      r.list!.single.label,
      (g['fromNothing']['list'] as List).first['label'],
    );
    expect(r.list!.single.amount, 75);
  });

  test('a refusal says WHICH rule it hit, which RN never does', () {
    // This app's own addition. RN returns silently on all three, so the person
    // taps Add, nothing appears, and nothing on screen says why.
    expect(addQuickAdd(const [], '  ', '100').error, 'Give it a name.');
    expect(
      addQuickAdd(const [], 'X', 'abc').error,
      'Enter an amount of at least 0.01, like 150 or 13.50.',
    );
    expect(
      addQuickAdd(const [], 'X', '0').error,
      'Enter an amount of at least 0.01, like 150 or 13.50.',
    );
    expect(
      addQuickAdd(const [QuickAdd('Food', 150)], 'fOOd', '99').error,
      'You already have a button called fOOd.',
    );
  });

  test('the three refusals RN does not have, each for a real harm', () {
    // Recorded as deliberate divergences, with the fixture holding RN's
    // answer beside each so nobody later "fixes" the port back.

    // RN accepts 0.004 and the chip then draws "Kape ₱0" while every tap
    // files a real expense. The silent-junk class, in a button.
    expect(
      addQuickAdd(const [], 'Kape', '0.004').error,
      'Enter an amount of at least 0.01, like 150 or 13.50.',
    );
    expect(addQuickAdd(const [], 'Kape', '0.01').list, isNotNull);

    // RN accepts any length, and a long one clipped the amount off the
    // Budget chip entirely, so the button logged a figure never shown.
    expect(
      addQuickAdd(
        const [],
        'Pamasahe papuntang opisina tapos pauwi',
        '92',
      ).error,
      'Keep the name short, 24 letters or less, so the amount still fits.',
    );
    expect(
      addQuickAdd(const [], 'Pamasahe papuntang opis', '92').list,
      isNotNull,
    );

    // RN refuses a comma too, but says nothing. The app prints ₱1,500 on
    // every screen, so typing it back is the obvious move, and "above zero"
    // is a confusing answer about a number that plainly is.
    expect(
      addQuickAdd(const [], 'Rent', '1,500').error,
      'Use a period for centavos, like 2.50. Commas only group thousands.',
    );
  });

  test('a stored quick add that would log money BACK is dropped', () {
    // A negative amount on a chip labelled "Food" would ADD to the budget on
    // every tap, and nothing on the chip would say so. Only reachable from a
    // hand edited backup, which is exactly when nobody is watching.
    final read = readQuickAdds([
      {'label': 'Food', 'amount': 150},
      {'label': 'Refund', 'amount': -50},
      {'label': 'Zero', 'amount': 0},
      {'label': 'Junk', 'amount': 'abc'},
      {'label': '', 'amount': 10},
      {'label': '   ', 'amount': 10},
      {'label': 'Inf', 'amount': double.infinity},
      'not a map',
    ]);
    expect(read, [const QuickAdd('Food', 150)]);
  });

  test('the shipped defaults match the RN defaults, in order', () {
    // Same four, same order, so somebody moving from the old app finds the
    // same buttons in the same places.
    expect(defaultQuickAdds.map((q) => q.label).toList(), [
      'Food',
      'Transport',
      'Coffee',
      'Load',
    ]);
    expect(defaultQuickAdds.map((q) => q.amount).toList(), [150, 50, 120, 100]);
  });
}
